  if (report.summary_status === 'not_applicable')
    return '本次没有足够的评价证据生成整场总结，可查看原回答和逐题分析。';
  if (report.status === 'failed') return '暂无成功的逐题分析，请先重试缺失分析。';
  return '逐题分析完成后整理整场总结，可以先查看下面已完成的题目。';
}

